PetType.CAT -> Cat( id = id, name = name, age = age.toInt(), weight = 3.0, breed = "", imageResId = imageResId, summary = "" )
else -> Parrot( id = id, name = name, age = age.toInt(), weight = 3.0, breed = "", imageResId = imageResId, wingSpan = 1.0, summary = "" ) } }
