package com.petcare.app.api

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.petcare.app.models.Pet
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.collect
import kotlinx.coroutines.launch

/**
 * ViewModel for API pet list screen
 * Manages network calls with error handling and offline support
 */
class ApiPetListViewModel(app: Application) : AndroidViewModel(app) {

    private val apiRepository = ApiRepository()

    private val _pets = MutableStateFlow<List<Pet>>(emptyList())
    val pets: StateFlow<List<Pet>> = _pets.asStateFlow()

    private val _isLoading = MutableStateFlow(false)
    val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

    private val _error = MutableStateFlow<String?>(null)
    val error: StateFlow<String?> = _error.asStateFlow()

    private val _searchQuery = MutableStateFlow("")
    val searchQuery: StateFlow<String> = _searchQuery.asStateFlow()

    private val _isDeletingId = MutableStateFlow<String?>(null)
    val isDeletingId: StateFlow<String?> = _isDeletingId.asStateFlow()

    private val _isOffline = MutableStateFlow(false)
    val isOffline: StateFlow<Boolean> = _isOffline.asStateFlow()

    private val _isCachedData = MutableStateFlow(false)
    val isCachedData: StateFlow<Boolean> = _isCachedData.asStateFlow()

    init {
        loadPets()
    }

    /**
     * Load all pets from API with error handling and caching
     */
    fun loadPets() {
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null

            try {
                apiRepository.getAllPets().collect { result ->
                    when (result) {
                        is ApiRepository.ApiResult.Success -> {
                            _pets.value = result.data
                            _isCachedData.value = result.isCached
                            _isOffline.value = false
                            _isLoading.value = false
                            _error.value = null
                        }
                        is ApiRepository.ApiResult.Error -> {
                            if (result.cachedData != null) {
                                // Show cached data with offline indicator
                                _pets.value = result.cachedData
                                _isOffline.value = true
                                _isCachedData.value = true
                                _error.value = "Offline mode - showing cached data"
                                _isLoading.value = false
                            } else {
                                // No cached data available
                                _error.value = "Network error: ${result.exception.message}"
                                _isLoading.value = false
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                _error.value = "Error: ${e.message ?: "Unknown error"}"
                _isLoading.value = false
            }
        }
    }

    /**
     * Search pets by name with error handling
     */
    fun searchPets(query: String) {
        _searchQuery.value = query
        if (query.isBlank()) {
            loadPets()
        } else {
            viewModelScope.launch {
                _isLoading.value = true
                _error.value = null

                try {
                    apiRepository.searchPets(query).collect { result ->
                        when (result) {
                            is ApiRepository.ApiResult.Success -> {
                                _pets.value = result.data
                                _isCachedData.value = result.isCached
                                _isOffline.value = false
                                _isLoading.value = false
                                _error.value = null
                            }
                            is ApiRepository.ApiResult.Error -> {
                                _error.value = "Search failed: ${result.exception.message}"
                                _isLoading.value = false
                            }
                        }
                    }
                } catch (e: Exception) {
                    _error.value = "Search error: ${e.message ?: "Unknown error"}"
                    _isLoading.value = false
                }
            }
        }
    }

    /**
     * Clear search and reload all pets
     */
    fun clearSearch() {
        _searchQuery.value = ""
        loadPets()
    }

    /**
     * Retry loading pets (useful after network errors)
     */
    fun retry() {
        if (_searchQuery.value.isBlank()) {
            loadPets()
        } else {
            searchPets(_searchQuery.value)
        }
    }

    /**
     * Delete pet from API (DEMO ONLY - API is read-only)
     * Shows demo message since API Ninjas doesn't support DELETE
     */
    fun deletePet(petId: String, petName: String) {
        viewModelScope.launch {
            _isDeletingId.value = petId
            try {
                val result = apiRepository.deletePet(petId)
                if (result.isSuccess) {
                    // Remove from local list
                    _pets.value = _pets.value.filter { it.id != petId.hashCode() }
                    _isDeletingId.value = null
                } else {
                    // API Ninjas is read-only, so DELETE will fail
                    // Show demo message instead of error
                    _error.value = "Demo: DELETE not supported by API Ninjas (read-only API). Animal removed from local list."
                    // Still remove from local list for demo purposes
                    _pets.value = _pets.value.filter { it.id != petId.hashCode() }
                    _isDeletingId.value = null
                }
            } catch (e: Exception) {
                // Show demo message
                _error.value = "Demo: DELETE not supported by API Ninjas (read-only API). Animal removed from local list."
                // Still remove from local list for demo purposes
                _pets.value = _pets.value.filter { it.id != petId.hashCode() }
                _isDeletingId.value = null
            }
        }
    }
}

