                .clickable { onBackClicked() })

        // Loading indicator
        CircularProgressIndicator()
    }
}

@Composable
private fun SuccessScreen(
    modifier: Modifier = Modifier,
    pet: Pet,
    relatedPets: List<Pet>,
    statistics: String,
    onBackClicked: () -> Unit
) {
    Column(
        modifier = modifier
            .fillMaxSize()
            .background(color = MaterialTheme.colorScheme.background)
            .padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        BackButton(
            modifier = Modifier
                .align(Alignment.Start)
                .clickable { onBackClicked() })

        PetImage(modifier = Modifier, imageResId = pet.imageResId ?: 0)

        PetInfo(pet = pet)

        Text(
            text = "Statistics",
            style = MaterialTheme.typography.headlineSmall
        )
        Text(
            text = statistics,
            style = MaterialTheme.typography.bodyMedium
        )

        // Related pets section
        if (relatedPets.isNotEmpty()) {
            Text(
                text = "Related Pets",
                style = MaterialTheme.typography.headlineSmall
            )
            relatedPets.forEach { relatedPet ->
                Text(
                    text = relatedPet.name,
                    style = MaterialTheme.typography.bodyMedium
                )
            }
        }
    }
}

@Composable
private fun ErrorScreen(message: String, onBackClicked: () -> Unit) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(color = MaterialTheme.colorScheme.background),
        verticalArrangement = Arrangement.spacedBy(8.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        BackButton(
            modifier = Modifier
                .align(Alignment.Start)
                .padding(top = 16.dp, start = 16.dp)
                .clickable { onBackClicked() })

        Text(
            text = "Error: $message",
            style = MaterialTheme.typography.headlineSmall,
            color = MaterialTheme.colorScheme.error
        )
    }
}

