package com.petcare.app.pet_profile

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import com.petcare.app.data.PetRepository
import com.petcare.app.models.Pet
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

sealed interface PetDetailState {
    data object Loading : PetDetailState
    data class Success(
        val pet: Pet,
        val relatedPets: List<Pet>,
        val statistics: String
    ) : PetDetailState
    data class Error(val message: String) : PetDetailState
}

class PetProfileViewModel(private val petId: Int) : ViewModel() {

    private val _state = MutableStateFlow<PetDetailState>(PetDetailState.Loading)
    val state: StateFlow<PetDetailState> = _state

    init {
        loadPetDetails()
    }

    private fun loadPetDetails() {
        viewModelScope.launch {
            _state.value = PetDetailState.Loading
            delay(500) // Simulate loading delay

            val pet = PetRepository.getPetById(petId)
            if (pet != null) {
                val relatedPets = computeRelatedPets(pet)
                val statistics = computeStatistics(pet)
                _state.value = PetDetailState.Success(pet, relatedPets, statistics)
            } else {
                _state.value = PetDetailState.Error("Pet not found")
            }
        }
    }

    private fun computeRelatedPets(pet: Pet): List<Pet> {
        // Return other pets of the same type, excluding the current pet
        return PetRepository.getAllPets()
            .filter { it.type == pet.type && it.id != pet.id }
            .take(3) // Limit to 3 related pets
    }

    private fun computeStatistics(pet: Pet): String {
        val allPets = PetRepository.getAllPets()
        val typeCount = allPets.count { it.type == pet.type }
        val totalPets = allPets.size
        val typePercentage = if (totalPets > 0) (typeCount * 100) / totalPets else 0

        return "Type: ${pet.type.title}\n" +
               "Pets of this type: $typeCount\n" +
               "Percentage: $typePercentage%\n" +
               "Total pets: $totalPets"
    }

    class Factory(private val petId: Int) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>): T {
            if (modelClass.isAssignableFrom(PetProfileViewModel::class.java)) {
                return PetProfileViewModel(petId) as T
            }
            throw IllegalArgumentException("Unknown ViewModel class")
        }
    }
}

package com.petcare.app.pet_profile

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import com.petcare.app.data.PetRepository
import com.petcare.app.models.Pet
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.collectLatest
import kotlinx.coroutines.launch

sealed interface PetDetailState {
    data object Loading : PetDetailState
    data class Success(
        val pet: Pet,
        val relatedPets: List<Pet>,
        val statistics: String
    ) : PetDetailState
    data class Error(val message: String) : PetDetailState
}

class PetProfileViewModel(private val petIdentifier: String) : ViewModel() {

    private val _state = MutableStateFlow<PetDetailState>(PetDetailState.Loading)
    val state: StateFlow<PetDetailState> = _state

    init {
        loadPetDetails()
    }

    private fun loadPetDetails() {
        viewModelScope.launch {
            _state.value = PetDetailState.Loading
            delay(500) // Simulate loading delay

            try {
                // Fetch pet from API by identifier (Task 3 requirement)
                PetRepository.getPetByIdentifier(petIdentifier).collectLatest { pet ->
                    if (pet != null) {
                        val relatedPets = computeRelatedPets(pet)
                        val statistics = computeStatistics(pet)
                        _state.value = PetDetailState.Success(pet, relatedPets, statistics)
                    } else {
                        _state.value = PetDetailState.Error("Pet not found")
                    }
                }
            } catch (e: Exception) {
                _state.value = PetDetailState.Error("Network error: ${e.message}")
            }
        }
    }

    private fun computeRelatedPets(pet: Pet): List<Pet> {
        // For related pets, we could fetch from API or use local data
        // For now, return empty list as we focus on main pet from API
        return emptyList()
    }

    private fun computeStatistics(pet: Pet): String {
        // Statistics based on the current pet data
        return "Type: ${pet.type}\n" +
               "Name: ${pet.name}\n" +
               "Age: ${pet.age} years\n" +
               "Weight: ${pet.weight} kg\n" +
               "Breed: ${pet.breed ?: "Unknown"}"
    }

    class Factory(private val petIdentifier: String) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>): T {
            if (modelClass.isAssignableFrom(PetProfileViewModel::class.java)) {
                return PetProfileViewModel(petIdentifier) as T
            }
            throw IllegalArgumentException("Unknown ViewModel class")
        }
    }
}

package com.petcare.app.data

import android.annotation.SuppressLint
import android.content.Context
import com.petcare.app.database.PetDatabase
import com.petcare.app.database.PetMapper
import com.petcare.app.models.Pet
import com.petcare.app.models.PetType
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map

@SuppressLint("StaticFieldLeak")
object PetRepository {

    lateinit var context: Context

    fun init(appContext: Context) {
        context = appContext.applicationContext
    }

    private val database by lazy { PetDatabase.getDatabase(context) }
    private val petDao by lazy { database.petDao() }

    val petsFlow: Flow<List<Pet>>
        get() = petDao.getAllPets().map { entities ->
            entities.map { PetMapper.toPet(it) }
        }

    val favoritePetsFlow: Flow<List<Pet>>
        get() = petDao.getFavoritePets().map { entities ->
            entities.map { PetMapper.toPet(it) }
        }

    fun getAllPets(): List<Pet> {
        return emptyList()
    }

    suspend fun addPet(pet: Pet) {
        val entity = PetMapper.toEntity(pet)
        petDao.insertPet(entity)
    }

    suspend fun removePet(pet: Pet) {
        val entity = PetMapper.toEntity(pet)
        petDao.deletePet(entity)
    }

    suspend fun toggleFavorite(petId: Int, isFavorite: Boolean) {
        petDao.updateFavoriteStatus(petId, isFavorite)
    }

    suspend fun getPetById(id: Int):  Pet? {
        return  petDao.getPetById(id)?.let { PetMapper.toPet(it)}
    }

    fun getPetTypes(): List<PetType> = PetType.entries

    fun getNextId(): Int {
        return 0
    }
}

package com.petcare.app.data

import android.annotation.SuppressLint
import android.content.Context
import com.petcare.app.api.ApiRepository
import com.petcare.app.database.PetDatabase
import com.petcare.app.database.PetMapper
import com.petcare.app.models.Pet
import com.petcare.app.models.PetType
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map

@SuppressLint("StaticFieldLeak")
object PetRepository {

    lateinit var context: Context
    private lateinit var apiRepository: ApiRepository

    fun init(appContext: Context) {
        context = appContext.applicationContext
        apiRepository = ApiRepository()
    }

    private val database by lazy { PetDatabase.getDatabase(context) }
    private val petDao by lazy { database.petDao() }

    // DATABASE OPERATIONS (for local data, favorites, etc.)
    val favoritePetsFlow: Flow<List<Pet>>
        get() = petDao.getFavoritePets().map { entities ->
            entities.map { PetMapper.toPet(it) }
        }

    suspend fun addPet(pet: Pet) {
        val entity = PetMapper.toEntity(pet)
        petDao.insertPet(entity)
    }

    suspend fun removePet(pet: Pet) {
        val entity = PetMapper.toEntity(pet)
        petDao.deletePet(entity)
    }

    suspend fun toggleFavorite(petId: Int, isFavorite: Boolean) {
        petDao.updateFavoriteStatus(petId, isFavorite)
    }

    fun getPetTypes(): List<PetType> = PetType.entries

    fun getNextId(): Int {
        return 0
    }

    // API OPERATIONS (for list screen and details screen - Task 3 requirement)

    /**
     * Get all pets from API (replaces database petsFlow for list screen)
     * Used by PetListViewModel for the main list
     */
    val petsFlow: Flow<List<Pet>>
        get() = apiRepository.getAllPets()

    /**
     * Get pet by identifier from API (replaces database getPetById for details screen)
     * Used by PetProfileViewModel for details screen
     * Note: Uses String identifier (name) instead of Int ID for API compatibility
     */
    suspend fun getPetByName(name: String): Pet? {
        // Since Flow operations need to be collected, we need to handle this differently
        // For now, return null - will be implemented properly in ViewModel
        return null
    }

    /**
     * Get pet by ID from database (kept for backward compatibility)
     */
    suspend fun getPetById(id: Int): Pet? {
        return petDao.getPetById(id)?.let { PetMapper.toPet(it) }
    }

    // API SEARCH FUNCTIONALITY

    /**
     * Search pets by name using API
     */
    fun searchPets(name: String): Flow<List<Pet>> {
        return apiRepository.searchPets(name)
    }

    /**
     * Get single pet by identifier from API
     * Returns Flow for reactive usage
     */
    fun getPetByIdentifier(identifier: String): Flow<Pet?> {
        return apiRepository.getPetById(identifier)
    }

    // LEGACY METHODS (kept for compatibility)
    fun getAllPets(): List<Pet> {
        return emptyList()
    }
}

